private fun firstARecord(data: ByteArray, length: Int): InetAddress? {
  if (length < 12) {
    return null
  }
  val answerCount = ((data[6].toInt() and 0xFF) shl 8) or (data[7].toInt() and 0xFF)
  var index = skipName(data, length, 12) + 4
  repeat(answerCount) {
    if (index >= length) {
      return null
    }
    index = skipName(data, length, index)
    if (index + 10 > length) {
      return null
    }
    val type = ((data[index].toInt() and 0xFF) shl 8) or (data[index + 1].toInt() and 0xFF)
    val size = ((data[index + 8].toInt() and 0xFF) shl 8) or (data[index + 9].toInt() and 0xFF)
    index += 10
    if (type == 1 && size == 4 && index + 4 <= length) {
      return InetAddress.getByAddress(data.copyOfRange(index, index + 4))
    }
    index += size
  }
  return null
}

