// The system resolver is tried first. Networks in Hong Kong and Southeast
// Asia normally answer correctly there and keep their local CDN edge. Public
// DNS is only asked when no system address presents a valid certificate for
// the host. If nothing verifies, the first reachable system address is used,
// which is what a direct WebView connection would have done. getaddrinfo also
// covers IPv6-only (NAT64) networks.
private static func connectUpstream(host: String, port: UInt16) -> Int32? {
  if host.contains(":") || inet_addr(host) != INADDR_NONE {
    return open(host: host, address: host, port: port, source: "literal")
  }
  let key = "\(host):\(port)"
  if let address = cachedAddress(key), let fd = open(host: host, address: address, port: port, source: "verified") {
    return fd
  }
  forget(key)

  let systemAddresses = resolveSystem(host: host)
  for address in systemAddresses where certificateMatches(host: host, address: address, port: port) {
    remember(key, address)
    if let fd = open(host: host, address: address, port: port, source: "system") {
      return fd
    }
  }

  let publicAddresses = publicLookup(host: host).filter { !systemAddresses.contains($0) }
  for address in publicAddresses where certificateMatches(host: host, address: address, port: port) {
    remember(key, address)
    if let fd = open(host: host, address: address, port: port, source: "public DNS") {
      return fd
    }
  }

  for address in systemAddresses + publicAddresses {
    if let fd = open(host: host, address: address, port: port, source: "unverified") {
      return fd
    }
  }
  return nil
}

private static func open(host: String, address: String, port: UInt16, source: String) -> Int32? {
