private static let stateLock = NSLock()
private static var verifiedAddresses: [String: (address: String, expiresAt: Date)] = [:]
private static var publicDnsPausedUntil = Date.distantPast
private static let verifiedLifetime: TimeInterval = 10 * 60
private static let publicDnsCooldown: TimeInterval = 60
private static let probeTimeout: TimeInterval = 6
