    return nil
  }
  return entry.address
}

private static func remember(_ key: String, _ address: String) {
  stateLock.lock()
  verifiedAddresses[key] = (address, Date().addingTimeInterval(verifiedLifetime))
  stateLock.unlock()
}

private static func forget(_ key: String) {
  stateLock.lock()
  verifiedAddresses[key] = nil
