// All candidates are checked at once and the first verified one wins, so a
// host with several dead addresses costs one timeout instead of one per address.
private fun probeAll(host: String, port: Int, addresses: List<InetAddress>): ProbeOutcome {
  if (addresses.isEmpty()) {
    return ProbeOutcome(null, emptyList())
  }
  val completion = ExecutorCompletionService<Pair<InetAddress, Probe>>(workers)
  addresses.forEach { address ->
    completion.submit { address to certificateMatches(host, address, port) }
  }
  val reachable = ArrayList<InetAddress>()
