private static let verifiedLifetime: TimeInterval = 10 * 60
private static let unreachableLifetime: TimeInterval = 30
private static let publicDnsCooldown: TimeInterval = 60
private static let probeTimeout: TimeInterval = 5
private static let probeQueue = DispatchQueue(label: "heals.webview-dns-proxy.probe", attributes: .concurrent)

private static func isUnreachable(_ key: String) -> Bool {
  stateLock.lock()
  defer { stateLock.unlock() }
  return (unreachableUntil[key] ?? .distantPast) > Date()
}

private static func markUnreachable(_ key: String) {
  stateLock.lock()
  unreachableUntil[key] = Date().addingTimeInterval(unreachableLifetime)
  stateLock.unlock()
}

