// The checkout page always hands over to the matching Yedpay host, so its
// address is verified while the member is still reading our payment page.
private val checkoutHandOff = mapOf(
  "payment.heals.asia" to "api.yedpay.com",
  "payment-stg.heals.asia" to "api-staging.yedpay.com",
)

private fun prewarm(host: String, port: Int) {
  val key = "$host:$port"
  val cached = verifiedAddresses[key]
  if (cached != null && cached.expiresAt > System.currentTimeMillis()) {
    return
  }
  workers.execute {
    try {
      val started = System.currentTimeMillis()
      val systemAddresses = InetAddress.getAllByName(host).toList()
      val verified = probeAll(host, port, systemAddresses).verified
        ?: probeAll(host, port, publicLookup(host).filter { it !in systemAddresses }).verified
      if (verified != null) {
        verifiedAddresses[key] = VerifiedAddress(verified, System.currentTimeMillis() + VERIFIED_TTL_MS)
        Log.i(TAG, "prewarmed $host -> ${verified.hostAddress} in ${System.currentTimeMillis() - started}ms")
      }
    } catch (error: Exception) {
      Log.w(TAG, "prewarm failed for $host: ${error.message}")
    }
  }
}

private fun connectUpstream(host: String, port: Int): Socket? {
  if (ipv4Literal.matches(host) || host.contains(':')) {
    return open(host, InetAddress.getByName(host), port, "literal")
  }
  checkoutHandOff[host]?.let { prewarm(it, port) }
  val key = "$host:$port"

