// The checkout page always hands over to the matching Yedpay host, so its
// address is verified while the member is still reading our payment page.
private static let checkoutHandOff = [
  "payment.heals.asia": "api.yedpay.com",
  "payment-stg.heals.asia": "api-staging.yedpay.com",
]

private static func prewarm(host: String, port: UInt16) {
  let key = "\(host):\(port)"
  if cachedAddress(key) != nil {
    return
  }
  DispatchQueue.global(qos: .utility).async {
    let started = Date()
    let systemAddresses = resolveSystem(host: host)
    var verified = probeAll(host: host, port: port, addresses: systemAddresses).verified
    if verified == nil {
      let publicAddresses = publicLookup(host: host).filter { !systemAddresses.contains($0) }
      verified = probeAll(host: host, port: port, addresses: publicAddresses).verified
    }
    if let address = verified {
      remember(key, address)
      NSLog("WebView public DNS proxy prewarmed \(host) -> \(address) in \(Int(Date().timeIntervalSince(started) * 1000))ms")
    }
  }
}

private enum Probe {
  case verified
  case certificateFailed
  case unreachable
}

